from pathlib import Path
import json,hashlib,shutil,re
root=Path(__file__).resolve().parents[2]
backup=Path(r'H:\DPH Backups\LearnerSharing_PreChange_20261012_233617')
manifest=json.loads((backup/'DPH_Backup_Verification.json').read_text(encoding='utf-8-sig'))
def sha(p):return hashlib.sha256(p.read_bytes()).hexdigest()
unchanged=[]
for entry in manifest['entries']:
 name=entry['path'].replace('\\','/')
 if name.startswith(('tests/fixtures/','docs/guides/','docs/pdf/','help/')) or name in ['DPH_Master_Development_Specification_v1.md','DPH_PHASE1_MASTER_REQUIREMENTS.md','DPH_CODEX_HANDOFF.txt']:
  assert sha(root/name)==entry['sha256'],name;unchanged.append(name)
reference=json.loads((root/'docs/reference-inventory.json').read_text(encoding='utf-8-sig'))
for entry in reference['files']:assert sha(root/'samples/reference-vcl2fmx-v6.0.0'/entry['path'])==entry['sha256'],entry['path']
sources=['DPH.Analysis.Explanations.pas','DPH.Publish.BrowserPolicy.pas','DPH.Publish.Export.pas','DPH.Publish.Model.pas','DPH.UI.Main.fmx','DPH.UI.Main.pas','tests/DPH.Tests.Publishing.dpr','tests/DPH.Tests.LearningRefocus.dpr','tests/DPH.Tests.GuidedTasks.dpr']
report={'result':'PASS learner sharing checkpoint; final documentation and independent acceptance remain','backup':str(backup),'backup_files':manifest['files'],'backup_bytes':manifest['bytes'],
 'checks':{'native_learning_with_reference':120,'guided_tasks_and_export':43,'profile':19,'publishing':121,'application':'PASS','native_form_binding':'PASS'},
 'offline_links':json.loads((root/'docs/learner-sharing-links.json').read_text()),'source_hashes':{n:sha(root/n) for n in sources},
 'unchanged_original_inputs_and_guides':unchanged,'unchanged_reference_files':len(reference['files']),
 'native_image':'docs/learner-sharing-learning-shared-lessons.png','image_content':'Actual DPH native WebView2 displaying exported lessons for a synthetic Delphi fixture',
 'manuals_review':'Still unread and deferred. Existing DPH guides and help unchanged. App-generated editable guides are pending the final documentation pass.',
 'human_beginner_acceptance':'not performed','historical_requirement_ledger':'unchanged; no false conversion of partial or missing records into implemented'}
(root/'docs/learner-sharing-verification.json').write_text(json.dumps(report,indent=2)+'\n',encoding='utf-8')
for source,target in [('phase1-profile-validation.json','learner-sharing-profile-regression.json'),('wp6-validation.json','learner-sharing-publishing-regression.json')]:
 shutil.copyfile(root/'bin/learner-sharing'/source,root/'docs'/target)
with (root/'docs/Learning_Refocus_Status.txt').open('a',encoding='utf-8',newline='') as f:f.write('\r\nLearner sharing checkpoint: 12 October 2026\r\nShared editions now start at learning.html with the twelve beginner topics,\r\nsaved questions/answers, real ordered task instructions and expected results,\r\nsupplied screenshots and business terms. Object links open the beginner\r\nexplanation with optional deeper details. Native Preview lessons opens this route.\r\nOptional publication settings start collapsed. Exports remain read-only and\r\nattributed, with the existing scoped redaction and integrity checks.\r\n120 native learning/reference, 43 guided task/export, 19 profile and 121 publishing\r\nchecks passed; application build and serialized form baseline passed. All 475\r\nlocal links across a 28-page scoped fixture edition resolved without external\r\nnavigation. Native browser evidence: learner-sharing-learning-shared-lessons.png.\r\nVerified pre-change backup: '+str(backup)+'\r\n'+str(manifest['files'])+' files; '+str(manifest['bytes'])+' bytes. All '+str(len(unchanged))+' original input/guide/help\r\nfiles and 2,430 pinned reference files remain unchanged.\r\nThe learning application corrections have reached their final documentation\r\npass. Read the owner review only now, fix the guides and app-generated editable\r\nlearning guide, and provide explicit run/test directions. Independent beginner\r\nacceptance has not occurred; do not claim it or complete historical parser gaps.\r\n')
# All of these directories were generated by named test executables/runners.
# The verified phase backup contains every pre-existing directory before cleanup.
pattern=re.compile(r'(?:phase1(?:-[a-z-]+)?|wp[1-7]|learning(?:-refocus)?|selection)-tests-(?:\{[0-9A-Fa-f-]{36}\}|\d{8}-\d{6}-\d{3})$')
removed=[]
for work in (root/'bin').iterdir():
 if not work.is_dir() or not pattern.fullmatch(work.name):continue
 assert work.resolve().parent==(root/'bin').resolve() and not work.is_symlink()
 assert not any(p.is_symlink() for p in work.rglob('*'))
 removed.append(work.name);shutil.rmtree(work)
for p in (root/'docs').glob('learner-sharing-*.png'):
 if p.name!='learner-sharing-learning-shared-lessons.png':p.unlink()
print('Recorded checkpoint. Preserved',len(unchanged),'original inputs/guides and 2430 reference files. Removed',len(removed),'disposable test directories.')
